INSERT INTO `media` VALUES (562,'Commercial Generator Power Plant','1-y7ja6x.webp','media/2026/09/1-y7ja6x.webp','public','image/webp',95752,'850x567','Commercial diesel generator power plant rental Dubai UAE','Heavy commercial diesel generator power plant installation in UAE',1,'2026-10-14 23:20:33','2026-10-14 23:20:33'),(563,'500 kVA Cummins Heavy Duty Diesel Generator','01-lptck9.jpg','media/2026/10/01-lptck9.jpg','public','image/jpeg',36263,'425x283','500 kVA Cummins diesel generator for rent in Dubai','500 kVA Cummins sound-attenuated diesel generator',1,'2026-10-14 23:20:33','2026-10-14 23:20:33'),(564,'Perkins 250 kVA Soundproof Canopy Generator','02-xbimnj.jpg','media/2026/10/02-xbimnj.jpg','public','image/jpeg',36482,'425x283','Perkins 250 kVA acoustic canopy generator rental UAE','Perkins 250 kVA soundproof acoustic generator',1,'2026-10-14 23:20:33','2026-10-14 23:20:33'),(565,'1000 kVA Prime Power Industrial Generator','03-8ab0vq.jpg','media/2026/10/03-8ab0vq.jpg','public','image/jpeg',28080,'425x283','1000 kVA heavy industrial generator rental in UAE','1000 kVA heavy industrial diesel generator for prime power',1,'2026-10-14 23:20:33','2026-10-14 23:20:33'),(566,'Sound-Attenuated Weatherproof Generator Unit','04-be9wys.jpg','media/2026/10/04-be9wys.jpg','public','image/jpeg',26622,'425x283','Weatherproof acoustic diesel generator hire in Dubai','Acoustic canopy weatherproof diesel generator unit',1,'2026-10-14 23:20:33','2026-10-14 23:20:33'),(567,'Mobile Trailer-Mounted Emergency Generator','05-6dnzah.jpg','media/2026/10/05-6dnzah.jpg','public','image/jpeg',32454,'425x283','Mobile trailer-mounted rapid response generator rental UAE','Emergency rapid deployment mobile generator on trailer',1,'2026-10-14 23:20:33','2026-10-14 23:20:33'),(568,'Construction Site Temporary Power Station','06-wx9o27.jpg','media/2026/10/06-wx9o27.jpg','public','image/jpeg',20140,'425x283','Temporary site power generator rental Dubai construction projects','Temporary power st