INSERT INTO `pages` VALUES (27,1,'Generator Rental in Dubai & UAE','home','','/storage/media/2026/09/1-y7ja6x.webp','home','published','Generator Rental in Dubai & UAE | 20 to 2500 kVA Power','Reliable diesel generator hire across Dubai, Abu Dhabi, and Northern Emirates with complete fuel logistics, load banking, and 24/7 technical support.',NULL,NULL,NULL,NULL,'https://generatordubai.com/storage/media/2026/09/1-y7ja6x.webp',0,'generator rental dubai',100,0,'2026-10-13 22:37:45','2026-10-14 23:49:21','{\"@context\":\"https://schema.org\",\"@type\":\"WebPage\",\"name\":\"Generator Rental Dubai\"}'),(28,1,'About Generator Dubai','about-us','<h2>Over a Decade of Temporary Power Engineering Across the UAE</h2><p>Generator Dubai was founded with a single mission: to deliver uncompromising electrical power continuity to the fastest-growing infrastructure and industrial developments in the Middle East.</p><p>With dedicated logistics yards in Dubai, Abu Dhabi, and Sharjah, our fleet of Tier-1 Cummins, Perkins, and Caterpillar generators guarantees dependable power for mega-events, civil construction, remote desert explorations, and emergency utility outages.</p>','/storage/media/2026/10/04-be9wys.jpg','about','published','About Generator Dubai | UAE Power Generation & Fleet History','Learn about Generator Dubai, the UAE leader in turnkey temporary power generation, heavy diesel fleet operations, and certified electrical engineering.',NULL,NULL,NULL,NULL,'https://generatordubai.com/storage/media/2026/10/04-be9wys.jpg',1,NULL,95,90,'2026-10-13 22:37:45','2026-10-14 16:20:30','{\n    \"@context\": \"https://schema.org\",\n    \"@graph\": [\n        {\n            \"@type\": \"AboutPage\",\n            \"@id\": \"https://generatordubai.com/about-us#about\",\n            \"name\": \"About Generator Dubai\",\n            \"description\": \"Learn about Generator Dubai, the UAE leader in turnkey temporary power generation, heavy diesel fleet operations, and certified electrical eng